/**
 * Deterministic seed for a fresh PostgreSQL database.
 *
 *   node src/db/seed.js
 *
 * Content mirrors the JSON seed exactly (same specialties, facilities,
 * services and doctor roster) so the API responses are comparable, but
 * ids are generated by the database and the slots come from the same
 * 14-day grid.
 *
 * Passwords are hashed with bcrypt here rather than in SQL, because the
 * cost factor must be explicit and `crypt()` availability varies.
 *
 * Idempotent: re-running produces the same counts.
 */
import { query, one, closePool } from "../config/database.js";
import { hashPassword } from "../utils/password.js";
import logger from "../utils/logger.js";

const log = logger.tag("seed");
// The business timezone, shared with the API so seeded slot times mean exactly
// what the endpoints that read them back mean.
const { TZ, localToInstant, todayLocal } = await import("../utils/time.js");

const SPECIALTIES = [
  ["Cardiology", "heart", "Heart and cardiovascular care"],
  ["Dermatology", "skin", "Skin, hair and nail conditions"],
  ["Pediatrics", "child", "Care for infants and children"],
  ["Orthopedics", "bone", "Bones, joints and musculoskeletal care"],
  ["Neurology", "brain", "Brain, spine and nervous system"],
  ["General Medicine", "stethoscope", "Primary and everyday healthcare"],
  ["Dentistry", "tooth", "Oral and dental health"],
  ["Ophthalmology", "eye", "Eye and vision care"],
  ["Psychiatry", "mind", "Mental health and wellbeing"],
  ["Gynecology", "health", "Women's health and maternity"],
];

const FACILITIES = [
  ["BookMyDoc City Hospital", "Bengaluru", "12 MG Road, Bengaluru", "Multi-specialty", 4.6],
  ["Sunrise Health Center", "Bengaluru", "44 Indiranagar, Bengaluru", "Clinic", 4.3],
  ["Apollo Care Clinic", "Mumbai", "8 Linking Road, Mumbai", "Multi-specialty", 4.5],
  ["GreenLife Clinic", "Delhi", "77 Nehru Place, Delhi", "Clinic", 4.2],
  ["Nova Diagnostics & Care", "Hyderabad", "5 Banjara Hills, Hyderabad", "Diagnostic Center", 4.1],
  ["Lakeview Medical Center", "Chennai", "31 Anna Salai, Chennai", "Multi-specialty", 4.4],
];

const SERVICES = [
  ["New Patient Consultation", 30, 800, "First visit with history review and physical exam"],
  ["Follow-up Consultation", 15, 400, "Review of ongoing treatment and progress"],
  ["Video Consultation", 20, 500, "Secure online consultation from home"],
  ["Health Screening Package", 90, 2500, "Complete preventive screening with reports"],
  ["Emergency Consultation", 30, 1500, "Priority urgent care slot"],
];

// [name, specialty, facility, city]
const DOCTORS = [
  ["Dr. Ananya Rao", "Cardiology", "BookMyDoc City Hospital", "Bengaluru"],
  ["Dr. Rohan Mehta", "Dermatology", "Sunrise Health Center", "Bengaluru"],
  ["Dr. Priya Sharma", "Pediatrics", "BookMyDoc City Hospital", "Bengaluru"],
  ["Dr. Karthik Iyer", "Orthopedics", "Lakeview Medical Center", "Chennai"],
  ["Dr. Sneha Kulkarni", "Neurology", "Apollo Care Clinic", "Mumbai"],
  ["Dr. Arjun Nair", "General Medicine", "GreenLife Clinic", "Delhi"],
  ["Dr. Meera Das", "Dentistry", "Nova Diagnostics & Care", "Hyderabad"],
  ["Dr. Vikram Singh", "Ophthalmology", "Apollo Care Clinic", "Mumbai"],
  ["Dr. Fatima Khan", "Psychiatry", "Sunrise Health Center", "Bengaluru"],
  ["Dr. Sanjay Gupta", "General Medicine", "Lakeview Medical Center", "Chennai"],
  ["Dr. Kavya Reddy", "Gynecology", "Nova Diagnostics & Care", "Hyderabad"],
  ["Dr. Aditya Bose", "Cardiology", "Lakeview Medical Center", "Chennai"],
];

const SLOT_TIMES = [
  "09:00", "09:30", "10:00", "10:30", "11:00", "11:30",
  "14:00", "14:30", "15:00", "16:00", "17:00",
];

const REASONS = [
  "Chest discomfort during exercise",
  "Recurring skin rash on arms",
  "Child fever and loss of appetite",
  "Knee pain while climbing stairs",
  "Frequent headaches and dizziness",
  "Annual health checkup",
  "Sensitive teeth while eating",
  "Blurred vision in left eye",
  "Sleep disturbance and stress",
  "Irregular menstrual cycles",
];

const slugify = (s) =>
  String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

/**
 * "2030-01-01" + "09:00" in the configured zone → an absolute instant.
 *
 * This used to subtract a fixed `TZ === "Asia/Kolkata" ? 5.5 : 0` offset, which
 * quietly assumed the project is deployed either in India or in UTC. Any other
 * zone produced seed data offset by hours from what the API would then report.
 */
const localInstant = localToInstant;

const addMinutes = (hhmm, mins) => {
  const [h, m] = hhmm.split(":").map(Number);
  const total = h * 60 + m + mins;
  return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
};

/**
 * The local date `n` days from today, in the business timezone.
 *
 * Adding 24 hours and reformatting was wrong on any day containing a daylight
 * saving transition, where the result lands on the wrong calendar date. This
 * steps the calendar date instead and renders it in the configured zone.
 */
const dayOffset = (n) => {
  const d = new Date(`${todayLocal()}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const seed = async () => {
  const already = await one("SELECT count(*)::int AS c FROM users");
  if (already.c > 0) {
    log.warn(`${already.c} user(s) already present — reseeding needs an empty database`);
    return;
  }

  console.log("\n=== Seeding PostgreSQL ===\n");

  /* ---------------- reference data ---------------- */
  const specIds = new Map();
  for (const [name, icon, description] of SPECIALTIES) {
    const r = await one(
      `INSERT INTO specialties (name, slug, description, icon) VALUES ($1,$2,$3,$4) RETURNING id`,
      [name, slugify(name), description, icon],
    );
    specIds.set(name, r.id);
  }
  console.log(`  specialties   ${SPECIALTIES.length}`);

  const facIds = new Map();
  for (const [name, city, address, type, rating] of FACILITIES) {
    const r = await one(
      `INSERT INTO facilities (name, city, address, type, rating, open_hours)
       VALUES ($1,$2,$3,$4,$5,'9:00 AM - 8:00 PM') RETURNING id`,
      [name, city, address, type, rating],
    );
    facIds.set(name, r.id);
  }
  console.log(`  facilities    ${FACILITIES.length}`);

  const svcIds = [];
  for (const [name, duration, price, description] of SERVICES) {
    const r = await one(
      `INSERT INTO services (name, description, duration_minutes, price)
       VALUES ($1,$2,$3,$4) RETURNING id`,
      [name, description, duration, price],
    );
    svcIds.push(r.id);
  }
  console.log(`  services      ${SERVICES.length}`);

  /* ---------------- users ---------------- */
  const patientPw = await hashPassword("patient123");
  const doctorPw = await hashPassword("doctor123");
  const adminPw = await hashPassword("admin123");

  const patientIds = [];
  const PATIENTS = [
    ["Rahul Verma", "patient@demo.com", "+91 90000 10001", "1994-06-15", "male", "O+"],
    ["Ishita Desai", "ishita@demo.com", "+91 90000 10002", "1992-03-08", "female", "A+"],
    ["Aman Verma", "aman@demo.com", "+91 90000 10003", "1988-11-21", "male", "B+"],
  ];

  for (const [name, email, phone, dob, gender, blood] of PATIENTS) {
    const u = await one(
      `INSERT INTO users (email, password_hash, role, full_name, phone)
       VALUES ($1,$2,'patient',$3,$4) RETURNING id`,
      [email, patientPw, name, phone],
    );
    await query(
      `INSERT INTO patient_profiles
         (user_id, date_of_birth, gender, blood_group, address_line, emergency_contact)
       VALUES ($1,$2,$3,$4,'45 Park Street, Bengaluru','+91 90000 11111')`,
      [u.id, dob, gender, blood],
    );
    await query(
      "INSERT INTO patient_allergies (patient_id, allergen) VALUES ($1,'Penicillin')",
      [u.id],
    );
    patientIds.push({ id: u.id, name });
  }

  await query(
    `INSERT INTO users (email, password_hash, role, full_name, phone)
     VALUES ('admin@demo.com',$1,'admin','System Admin','+91 90000 00000')`,
    [adminPw],
  );
  console.log(`  users         ${PATIENTS.length + 1} (patients + admin)`);

  /* ---------------- doctors ---------------- */
  const doctorRows = [];
  for (const [idx, [name, specialty, facility, city]] of DOCTORS.entries()) {
    const u = await one(
      `INSERT INTO users (email, password_hash, role, full_name, phone)
       VALUES ($1,$2,'doctor',$3,$4) RETURNING id`,
      [
        `doctor${idx + 1}@demo.com`,
        doctorPw,
        name,
        `+91 90000 2${String(idx + 1).padStart(4, "0")}`,
      ],
    );

    const experience = 5 + idx * 2;
    const fee = 500 + idx * 150;
    const d = await one(
      `INSERT INTO doctors
         (user_id, specialty_id, facility_id, qualification, experience_years,
          bio, consultation_fee, is_accepting_new, avatar_color,
          seed_rating, seed_review_count)
       VALUES ($1,$2,$3,$4,$5,$6,$7,true,$8,$9,$10) RETURNING id, facility_id`,
      [
        u.id,
        specIds.get(specialty),
        facIds.get(facility),
        idx % 3 === 0 ? "MD, DM - Cardiology" : "MBBS, MD",
        experience,
        `${name} is a highly experienced ${specialty.toLowerCase()} specialist with over ${experience} years of clinical practice at ${facility}.`,
        fee,
        ["#2563eb", "#7c3aed", "#059669", "#dc2626", "#d97706"][idx % 5],
        Number((4 + (idx % 5) * 0.2).toFixed(1)),
        40 + idx * 37,
      ],
    );

    for (const sid of svcIds.slice(0, 3)) {
      await query(
        "INSERT INTO doctor_services (doctor_id, service_id) VALUES ($1,$2)",
        [d.id, sid],
      );
    }
    for (const lang of idx % 2 === 0 ? ["English", "Kannada", "Hindi"] : ["English", "Hindi"]) {
      await query(
        "INSERT INTO doctor_languages (doctor_id, language) VALUES ($1,$2)",
        [d.id, lang],
      );
    }

    doctorRows.push({ id: d.id, facilityId: d.facility_id, name, specialty, fee, city });
  }
  console.log(`  doctors       ${DOCTORS.length}`);

  /* ---------------- slots (14 days) ---------------- */
  let slotCount = 0;
  const insertSlot = async (doctor, date, time, status, mode) => {
    try {
      await query(
        `INSERT INTO slots (doctor_id, facility_id, starts_at, ends_at, mode, status, fee)
         VALUES ($1,$2,$3,$4,$5,$6,$7)`,
        [
          doctor.id,
          doctor.facilityId,
          localInstant(date, time),
          localInstant(date, addMinutes(time, 30)),
          mode,
          status,
          doctor.fee,
        ],
      );
      slotCount += 1;
    } catch (err) {
      // The exclusion constraint rejects overlapping slots; that is the
      // schema working, not a seed failure.
      if (!["23P01", "23505"].includes(err.code)) throw err;
    }
  };

  // The grid runs from 30 days ago to 13 days ahead.
  //
  // It used to start at today, so every slot was in the future - which meant a
  // 'completed' appointment could only be attached to a slot that had not
  // happened yet. Past slots give the seeded history something real to sit on.
  for (let day = -30; day < 14; day += 1) {
    const date = dayOffset(day);
    for (const [dIdx, doc] of doctorRows.entries()) {
      // Stagger doctors so the grid is not identical for everyone.
      const times = SLOT_TIMES.filter((_, i) => (i + dIdx) % 2 === 0 || day % 3 === 0);
      for (const [tIdx, time] of times.entries()) {
        const roll = (day * 7 + dIdx * 3 + tIdx * 5) % 10;
        // Slots are inserted as 'available', or 'blocked' where the seed wants a
        // provider to have closed that time.
        //
        // They used to be rolled as 'booked' here, at random, and never
        // reconciled with the appointments created further down. That left ~500
        // slots advertised as taken with nothing behind them, so a "booked" slot
        // carried no information and the booking directory disagreed with the
        // appointment list. 'booked' is now DERIVED from the appointments that
        // actually exist - see reconcileSlotStatuses() below - so the flag always
        // means the same thing it does in the running system.
        const status = roll < 2 ? "blocked" : "available";
        const mode = tIdx % 4 === 3 ? "video" : "in-person";
        await insertSlot(doc, date, time, status, mode);
      }
    }
  }
  console.log(`  slots         ${slotCount}`);

  /* ---------------- appointment history ---------------- */
  const STATUSES = [
    "completed", "completed", "completed", "cancelled", "no-show",
    "confirmed", "in-progress",
  ];

  let aptCount = 0;
  const insertApt = async (row) => {
    try {
      // Booked a few days before the slot it refers to, so the audit timestamps
      // cannot postdate the appointment they describe.
      const created = new Date(row.slot.starts_at.getTime() - 3 * 86400_000);
      const r = await one(
        `INSERT INTO appointments
           (patient_id, doctor_id, slot_id, specialty_id, facility_id, mode,
            status, reason, symptoms, fee, cancel_reason, cancelled_at,
            cancelled_by, created_at, starts_at, ends_at)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$8,$9,$10,$11,$12,$13,$14,$15)
         RETURNING id`,
        [
          row.patient.id,
          row.doctor.id,
          row.slotId,
          specIds.get(row.doctor.specialty),
          row.doctor.facilityId,
          row.slot.mode,
          row.status,
          row.reason,
          row.fee,
          row.status === "cancelled" ? (row.reason || "Cancelled by patient") : null,
          row.status === "cancelled" ? created : null,
          row.status === "cancelled" ? "patient" : null,
          created,
          // The window is copied from the SLOT, never recomputed from the
          // appointment's own date and time.
          //
          // `appointments.starts_at` / `ends_at` are what the API renders as the
          // appointment's date and time (DATE_EXPR reads the appointment, not the
          // slot), and what `appointments_patient_no_overlap` evaluates. Deriving
          // them independently meant every seeded appointment displayed a time
          // that disagreed with the slot it was attached to, and the patient
          // overlap constraint was being tested against the wrong times.
          row.slot.starts_at,
          row.slot.ends_at,
        ],
      );
      // The audit trail records who changed a status, so `changed_by` is set.
      // It was left NULL, which made every seeded appointment look as though it
      // had materialised with nobody's involvement - and unlike a real system,
      // where NULL legitimately means "a system-initiated transition", here the
      // creator was always known: it is the patient.
      //
      // One row per seeded appointment is a simplification, not a claim that the
      // appointment jumped straight to its status: the note says it is seeded
      // history. The alternative - fabricating a chain of intermediate
      // transitions with invented timestamps - would assert events that did not
      // happen.
      await query(
        `INSERT INTO appointment_status_history
           (appointment_id, from_status, to_status, changed_by, note)
         VALUES ($1, NULL, $2, $3, 'Seeded historical appointment')`,
        [r.id, row.status, row.patient.id],
      );
      aptCount += 1;
    } catch (err) {
      // Skip historical rows that collide with the new constraints.
      if (!["23P01", "23505", "23503", "23514"].includes(err.code)) throw err;
    }
  };

  // Each historical appointment is anchored to a DISTINCT slot. The schema
  // permits only one active appointment per slot
  // (appointments_one_active_per_slot), so reusing a slot for a second
  // active record is rejected by the database — which is the constraint
  // working correctly, not a seed failure.
  const allSlots = (
    await query(
      `SELECT sl.id, sl.doctor_id, sl.facility_id, sl.starts_at, sl.ends_at, sl.mode
         FROM slots sl ORDER BY sl.starts_at`,
    )
  ).rows;

  const NOW = Date.now();
  const TERMINAL = ["completed", "cancelled", "no-show"];

  /** Slots grouped by doctor, consumed as they are assigned. */
  const slotsByDoctor = new Map();
  for (const s of allSlots) {
    if (!slotsByDoctor.has(s.doctor_id)) slotsByDoctor.set(s.doctor_id, []);
    slotsByDoctor.get(s.doctor_id).push(s);
  }
  const usedSlots = new Set();
  const patientTimes = new Map();

  /**
   * Next unused slot for a doctor, or null when none is left.
   *
   * `when` keeps history honest: a completed, cancelled or no-show appointment
   * belongs on a slot that has already passed, and a confirmed or in-progress one
   * on a slot still to come. Without that filter the seed attached finished
   * visits to future slots.
   */
  const takeSlot = (doctorId, patientId, when = "any") => {
    const pool = slotsByDoctor.get(doctorId) || [];
    for (const s of pool) {
      if (usedSlots.has(s.id)) continue;
      const isPast = s.starts_at.getTime() < NOW;
      if (when === "past" && !isPast) continue;
      if (when === "future" && isPast) continue;
      // An active record must not overlap another active record for the
      // same patient (appointments_patient_no_overlap).
      const key = `${patientId}|${s.starts_at.toISOString()}`;
      if (patientTimes.has(key)) continue;
      usedSlots.add(s.id);
      patientTimes.set(key, true);
      return s;
    }
    return null;
  };

  for (let i = 0; i < 42; i += 1) {
    const doc = doctorRows[i % doctorRows.length];
    const patient = patientIds[i % patientIds.length];
    const status = STATUSES[i % STATUSES.length];

    const candidate = takeSlot(doc.id, patient.id, TERMINAL.includes(status) ? "past" : "future");
    if (!candidate) continue;

    await insertApt({
      patient,
      doctor: doc,
      slot: candidate,
      slotId: candidate.id,
      status,
      reason: REASONS[i % REASONS.length],
      fee: doc.fee,
    });
  }

  // Two upcoming appointments for the first patient.
  for (const [i, docIdx] of [0, 5].entries()) {
    const doc = doctorRows[docIdx];
    const candidate = takeSlot(doc.id, patientIds[0].id, "future");
    if (!candidate) continue;
    await insertApt({
      patient: patientIds[0],
      doctor: doc,
      slot: candidate,
      slotId: candidate.id,
      status: i === 0 ? "confirmed" : "scheduled",
      reason: "Follow-up consultation",
      fee: doc.fee,
    });
  }

  /*
   * Reconcile slot status with reality.
   *
   * A slot is 'booked' exactly when an active appointment points at it, and is
   * otherwise left as seeded ('available' or 'blocked'). Deriving the flag in one
   * place - after every appointment exists - is what makes the two tables agree,
   * and it is the same rule the booking service enforces at runtime:
   *
   *   appointments_one_active_per_slot  => at most one active appointment
   *   a booked slot with no active appointment => nobody can book it again
   *
   * Terminal appointments (completed / cancelled / no-show) deliberately leave
   * the slot bookable, matching what cancel() and changeStatus() do: releasing
   * the slot is how a provider's calendar becomes reusable.
   */
  const reconciled = await query(
    `UPDATE slots sl
        SET status = CASE WHEN EXISTS (
              SELECT 1 FROM appointments a
               WHERE a.slot_id = sl.id
                 AND a.status IN ('scheduled','confirmed','in-progress')
            ) THEN 'booked'::slot_status
            WHEN sl.status = 'blocked' THEN 'blocked'::slot_status
            ELSE 'available'::slot_status
          END
      WHERE sl.status IS DISTINCT FROM CASE WHEN EXISTS (
              SELECT 1 FROM appointments a
               WHERE a.slot_id = sl.id
                 AND a.status IN ('scheduled','confirmed','in-progress')
            ) THEN 'booked'::slot_status
            WHEN sl.status = 'blocked' THEN 'blocked'::slot_status
            ELSE 'available'::slot_status
          END`,
  );
  const bookedSlots = await one(
    `SELECT count(*)::int AS c FROM slots WHERE status = 'booked'`,
  );
  console.log(`  appointments  ${aptCount}`);
  console.log(`  slot status   reconciled (${reconciled.rowCount} changed, ${bookedSlots.c} booked)`);

  await query(
    `INSERT INTO seed_metadata (key, value, updated_at)
     VALUES ('seed', $1::jsonb, now())
     ON CONFLICT (key) DO UPDATE SET value = $1::jsonb, updated_at = now()`,
    [
      JSON.stringify({
        seededAt: new Date().toISOString(),
        timezone: TZ,
        counts: {
          doctors: DOCTORS.length,
          slots: slotCount,
          appointments: aptCount,
          bookedSlots: bookedSlots.c,
        },
      }),
    ],
  );

  const totals = await Promise.all(
    ["users", "doctors", "specialties", "facilities", "services", "slots", "appointments"].map(
      async (t) => {
        const r = await one(`SELECT count(*)::int AS c FROM ${t}`);
        return `    ${t.padEnd(14)} ${r.c}`;
      },
    ),
  );
  console.log("\n  Totals:");
  console.log(totals.join("\n"));
  console.log("\n  Seed complete.\n");
};

run().catch(async (err) => {
  console.error(`\n  Seed failed: ${err.message}`);
  if (err.code) console.error(`  SQLSTATE ${err.code}`);
  if (err.hint) console.error(`  hint: ${err.hint}`);
  console.error("");
  await closePool();
  process.exit(1);
});

async function run() {
  try {
    await seed();
    await closePool();
  } catch (err) {
    await closePool();
    process.exit(1);
  }
}